import { useMemo, useState, type ReactNode } from "react";
import { formatMoney } from "../rateCard/cards";
import { applicableOnRequestRows, calculateActivityQuote, type ActivityCharge, type ActivityDateAdjustment, type ActivityMethod, type ActivityOption, type ActivityQuoteInput, type ActivityRateState, type ActivityTariff, type BookingRate, type PersonRate, type UnitRate } from "../rateCard/activityPricing";
import type { RateCardDetail } from "../rateCard/types";
import "./RegionalTransportWorkbook.css";
import "./ActivityRateWorkspace.css";

const methods: Array<{ id: ActivityMethod; label: string; description: string }> = [
  { id: "person", label: "Per person", description: "Shared tickets or individual places" },
  { id: "booking", label: "Per booking/group", description: "One price for a private party" },
  { id: "unit", label: "Per unit", description: "Equipment or vehicle quantities" },
];
const states: Array<[ActivityRateState, string]> = [["priced", "Priced"], ["complimentary", "Complimentary"], ["on-request", "On request"], ["missing", "Missing"], ["not-offered", "Not offered"]];
const asNumber = (value: string): number | null => value === "" ? null : Number(value);
const id = (prefix: string) => `${prefix}-${crypto.randomUUID().slice(0, 8)}`;
const show = (value: string | number | null | undefined) => value === "" || value == null ? "—" : value;

function Section({ title, note, action, children }: { title: string; note?: string; action?: ReactNode; children: ReactNode }) {
  return <section className="rtw-section activity-rate__section"><div className="rtw-section__head"><div><h2>{title}</h2>{note ? <p>{note}</p> : null}</div>{action}</div>{children}</section>;
}

function OptionScope({ value, allOptions, options, editing, onChange }: { value: string[]; allOptions?: boolean; options: ActivityOption[]; editing: boolean; onChange: (next: string[], all: boolean) => void }) {
  if (!editing) return <span>{allOptions ? "All options" : value.length ? value.map((optionId) => options.find((option) => option.id === optionId)?.name ?? optionId).join(", ") : "No option selected"}</span>;
  return <details className="activity-rate__scope"><summary>{allOptions ? "All options" : value.length ? `${value.length} option${value.length === 1 ? "" : "s"}` : "Select options"}</summary><div><label><input type="checkbox" checked={!!allOptions} onChange={(event) => onChange([], event.target.checked)} /> All options</label>{options.map((option) => <label key={option.id}><input type="checkbox" checked={value.includes(option.id)} onChange={(event) => onChange(event.target.checked ? [...value, option.id] : value.filter((item) => item !== option.id), false)} /> {option.name}</label>)}</div></details>;
}

export function ActivityRateDetails({ card, options, editing, onChange }: { card: RateCardDetail; options: ActivityOption[]; editing: boolean; onChange: (tariff: ActivityTariff) => void }) {
  const tariff = card.activityTariff!;
  const patch = (update: Partial<ActivityTariff>) => onChange({ ...tariff, ...update });
  const text = (value: string, label: string, update: (next: string) => void) => editing ? <input className="rtw-input" aria-label={label} value={value} onChange={(event) => update(event.target.value)} /> : <span>{show(value)}</span>;
  const number = (value: number | null, label: string, update: (next: number | null) => void, isMoney = false) => editing ? <input className="rtw-input rtw-input--number" type="number" min="0" aria-label={label} value={value ?? ""} onChange={(event) => update(asNumber(event.target.value))} /> : <span className={isMoney ? "rtw-money" : ""}>{value == null ? "—" : isMoney ? formatMoney(value, card.currency) : value}</span>;
  const select = <T extends string>(value: T, label: string, choices: Array<[T, string]>, update: (next: T) => void) => editing ? <select className="rtw-input" aria-label={label} value={value} onChange={(event) => update(event.target.value as T)}>{choices.map(([key, name]) => <option key={key} value={key}>{name}</option>)}</select> : <span>{choices.find(([key]) => key === value)?.[1] ?? value}</span>;
  const optionSelect = (optionId: string, label: string, update: (next: string) => void) => editing ? <select className="rtw-input" aria-label={label} value={optionId} onChange={(event) => update(event.target.value)}>{options.map((option) => <option key={option.id} value={option.id}>{option.name}</option>)}</select> : <span className="activity-rate__option">{options.find((option) => option.id === optionId)?.name ?? "Option removed"}</span>;
  const price = (rate: { state: ActivityRateState; amount: number | null }, label: string, update: (next: { state?: ActivityRateState; amount?: number | null }) => void) => editing ? <div className="activity-rate__price-edit">{select(rate.state, `${label} state`, states, (state) => update({ state, amount: state === "complimentary" ? 0 : state === "priced" ? rate.amount : null }))}{rate.state === "priced" ? number(rate.amount, `${label} supplier rate`, (amount) => update({ amount }), true) : null}</div> : <span className={`activity-rate__price activity-rate__price--${rate.state}`}><strong>{rate.state === "priced" ? rate.amount == null ? "Missing" : formatMoney(rate.amount, card.currency) : states.find(([state]) => state === rate.state)?.[1]}</strong></span>;
  const updatePerson = (rowId: string, update: Partial<PersonRate>) => patch({ personRates: tariff.personRates.map((row) => row.id === rowId ? { ...row, ...update } : row) });
  const updateBooking = (rowId: string, update: Partial<BookingRate>) => patch({ bookingRates: tariff.bookingRates.map((row) => row.id === rowId ? { ...row, ...update } : row) });
  const updateUnit = (rowId: string, update: Partial<UnitRate>) => patch({ unitRates: tariff.unitRates.map((row) => row.id === rowId ? { ...row, ...update } : row) });
  const updateCharge = (rowId: string, update: Partial<ActivityCharge>) => patch({ charges: tariff.charges.map((row) => row.id === rowId ? { ...row, ...update } : row) });
  const updateAdjustment = (rowId: string, update: Partial<ActivityDateAdjustment>) => patch({ adjustments: tariff.adjustments.map((row) => row.id === rowId ? { ...row, ...update } : row) });
  const remove = (label: string, action: () => void) => editing ? <button className="rtw-button" type="button" onClick={action} aria-label={`Remove ${label}`}>Remove</button> : null;
  return <div className="rtw-workbook activity-rate">
    <Section title="Rate-card information"><div className="activity-rate__facts">
      <div><span>Supplying vendor</span><strong>{card.vendor}</strong></div><div><span>Offered activity</span><strong>{card.property}</strong></div><div><span>Currency</span><strong>{card.currency}</strong></div><div><span>Price type</span><strong>Supplier cost</strong></div>
      <label><span>Valid from</span>{editing ? <input className="rtw-input" type="date" value={tariff.validFrom} onChange={(event) => patch({ validFrom: event.target.value })} /> : <strong>{show(tariff.validFrom)}</strong>}</label>
      <label><span>Valid until</span>{editing ? <input className="rtw-input" type="date" value={tariff.validTo} onChange={(event) => patch({ validTo: event.target.value })} /> : <strong>{show(tariff.validTo)}</strong>}</label>
      <label className="activity-rate__wide"><span>Supplier source document</span>{text(tariff.sourceDocument, "Supplier source document", (sourceDocument) => patch({ sourceDocument }))}</label>
      <label className="activity-rate__full"><span>Supplier numbers</span>{select(tariff.sourceConfirmed ? "yes" : "no", "Supplier numbers confirmed", [["no", "Pending confirmation"], ["yes", "Confirmed"]], (value) => patch({ sourceConfirmed: value === "yes" }))}</label>
    </div></Section>

    <Section title="Pricing methods" note="Select the methods this supplier offers. Each selected option uses one base method per quote."><div className="activity-rate__methods">{methods.map((method) => <label key={method.id} className={tariff.methods.includes(method.id) ? "is-selected" : ""}><input type="checkbox" disabled={!editing} checked={tariff.methods.includes(method.id)} onChange={(event) => patch({ methods: event.target.checked ? [...tariff.methods, method.id] : tariff.methods.filter((item) => item !== method.id) })} /><span><strong>{method.label}</strong><small>{method.description}</small></span></label>)}</div></Section>

    {options.some((option) => option.minParticipants != null) ? <Section title="Minimum booking charges" note="The service sets the minimum party size. Only an agreed minimum bill permits smaller parties."><div className="rtw-scroll"><table className="rtw-table"><thead><tr><th>Service option</th><th>Minimum participants</th><th>Supplier minimum bill</th></tr></thead><tbody>{options.filter((option) => option.minParticipants != null).map((option) => <tr key={option.id}><th scope="row">{option.name}</th><td>{option.minParticipants}</td><td>{number(tariff.minimumCharges?.find((item) => item.optionId === option.id)?.amount ?? null, `${option.name} minimum bill`, (amount) => patch({ minimumCharges: [...(tariff.minimumCharges ?? []).filter((item) => item.optionId !== option.id), ...(amount == null ? [] : [{ optionId: option.id, amount }])] }), true)}</td></tr>)}</tbody></table></div></Section> : null}

    {tariff.methods.includes("person") ? <Section title="Per-person rates" note="Participant categories and optional age bands belong to each service option." action={editing && options.length ? <button className="rtw-button" type="button" onClick={() => patch({ personRates: [...tariff.personRates, { id: id("person"), optionId: options[0].id, category: "Everyone", minAge: null, maxAge: null, minGroup: null, maxGroup: null, state: "missing", amount: null }] })}>Add person rate</button> : undefined}><div className="rtw-scroll"><table className="rtw-table"><thead><tr><th>Option</th><th>Participant category</th><th>Age range</th><th>Supplier rate</th>{editing ? <th>Action</th> : null}</tr></thead><tbody>{tariff.personRates.map((row) => <tr key={row.id}><td>{optionSelect(row.optionId, "Rate option", (optionId) => updatePerson(row.id, { optionId }))}</td><td>{editing ? <input className="rtw-input" list="activity-participant-categories" aria-label="Participant category" value={row.category} onChange={(event) => updatePerson(row.id, { category: event.target.value, minAge: event.target.value === "Everyone" ? null : row.minAge, maxAge: event.target.value === "Everyone" ? null : row.maxAge })} /> : <strong>{row.category}</strong>}{editing && row.category !== "Everyone" ? <label className="activity-rate__check"><input type="checkbox" checked={row.minAge != null || row.maxAge != null} onChange={(event) => updatePerson(row.id, { minAge: event.target.checked ? 0 : null, maxAge: null })} /> Age-based</label> : null}{editing || row.minGroup != null || row.maxGroup != null ? <details className="activity-rate__tiers"><summary>Group size tier: {row.minGroup ?? "Any"}–{row.maxGroup ?? "Any"}</summary>{editing ? <div>{number(row.minGroup, "Minimum group size", (minGroup) => updatePerson(row.id, { minGroup }))}{number(row.maxGroup, "Maximum group size", (maxGroup) => updatePerson(row.id, { maxGroup }))}</div> : <small>Rate applies when party size is in this band.</small>}</details> : null}</td><td>{row.category === "Everyone" || row.minAge == null && row.maxAge == null ? "All ages" : <div className="activity-rate__range">{number(row.minAge, "Minimum age", (minAge) => updatePerson(row.id, { minAge }))}<span>to</span>{number(row.maxAge, "Maximum age", (maxAge) => updatePerson(row.id, { maxAge }))}</div>}</td><td>{price(row, row.category, (next) => updatePerson(row.id, next))}</td>{editing ? <td>{remove(row.category, () => patch({ personRates: tariff.personRates.filter((item) => item.id !== row.id) }))}</td> : null}</tr>)}</tbody></table></div>{!tariff.personRates.length ? <div className="rtw-table-foot">Add a participant rate to price this method.</div> : null}<datalist id="activity-participant-categories"><option value="Everyone" /><option value="Adult" /><option value="Child" /><option value="Infant" /><option value="Senior" /></datalist></Section> : null}

    {tariff.methods.includes("booking") ? <Section title="Per-booking/group rates" note="The amount is charged once for the selected private booking or group." action={editing && options.length ? <button className="rtw-button" type="button" onClick={() => patch({ bookingRates: [...tariff.bookingRates, { id: id("booking"), optionId: options[0].id, minGroup: 1, maxGroup: 1, basisLabel: "Per booking", state: "missing", amount: null }] })}>Add group rate</button> : undefined}><div className="rtw-scroll"><table className="rtw-table"><thead><tr><th>Option</th><th>Group size</th><th>Charging basis</th><th>Supplier rate</th>{editing ? <th>Action</th> : null}</tr></thead><tbody>{tariff.bookingRates.map((row) => <tr key={row.id}><td>{optionSelect(row.optionId, "Group option", (optionId) => updateBooking(row.id, { optionId }))}</td><td><div className="activity-rate__range">{number(row.minGroup, "Minimum group size", (minGroup) => updateBooking(row.id, { minGroup: minGroup ?? 1 }))}<span>to</span>{number(row.maxGroup, "Maximum group size", (maxGroup) => updateBooking(row.id, { maxGroup: maxGroup ?? 1 }))}</div></td><td>{select(row.basisLabel, "Charging basis", [["Per booking", "Per booking"], ["Per group", "Per group"]], (basisLabel) => updateBooking(row.id, { basisLabel }))}</td><td>{price(row, row.basisLabel, (next) => updateBooking(row.id, next))}</td>{editing ? <td>{remove("group rate", () => patch({ bookingRates: tariff.bookingRates.filter((item) => item.id !== row.id) }))}</td> : null}</tr>)}</tbody></table></div>{!tariff.bookingRates.length ? <div className="rtw-table-foot">Add a group-size band to price this method.</div> : null}</Section> : null}

    {tariff.methods.includes("unit") ? <Section title="Per-unit rates" note="Unit quantity is entered explicitly in the proposal; capacity only validates the selection." action={editing && options.length ? <button className="rtw-button" type="button" onClick={() => patch({ unitRates: [...tariff.unitRates, { id: id("unit"), optionId: options[0].id, unit: "Unit", basis: "session", duration: null, capacityPerUnit: null, state: "missing", amount: null }] })}>Add unit rate</button> : undefined}><div className="rtw-scroll"><table className="rtw-table"><thead><tr><th>Option</th><th>Unit</th><th>Duration / basis</th><th>Capacity per unit</th><th>Supplier rate</th>{editing ? <th>Action</th> : null}</tr></thead><tbody>{tariff.unitRates.map((row) => <tr key={row.id}><td>{optionSelect(row.optionId, "Unit option", (optionId) => updateUnit(row.id, { optionId }))}</td><td>{text(row.unit, "Unit name", (unit) => updateUnit(row.id, { unit }))}</td><td><div className="activity-rate__basis">{select(row.basis, "Unit charging basis", [["session", "Fixed session"], ["hour", "Hourly"], ["day", "Daily"]], (basis) => updateUnit(row.id, { basis }))}{row.basis === "session" ? <span>{number(row.duration, "Session duration in hours", (duration) => updateUnit(row.id, { duration }))} {row.duration ? "hours included" : ""}</span> : null}</div></td><td>{number(row.capacityPerUnit, "Capacity per unit", (capacityPerUnit) => updateUnit(row.id, { capacityPerUnit }))}</td><td>{price(row, row.unit, (next) => updateUnit(row.id, next))}</td>{editing ? <td>{remove(row.unit, () => patch({ unitRates: tariff.unitRates.filter((item) => item.id !== row.id) }))}</td> : null}</tr>)}</tbody></table></div>{!tariff.unitRates.length ? <div className="rtw-table-foot">Add an equipment or vehicle rate to price this method.</div> : null}</Section> : null}

    <Section title="Additional charges and inclusions" note="Each charge applies to selected service options or explicitly to all options." action={editing ? <button className="rtw-button" type="button" onClick={() => patch({ charges: [...tariff.charges, { id: id("charge"), name: "New charge", optionIds: [], allOptions: false, treatment: "additional", mandatory: true, basis: "booking", amount: null, taxProfileId: null }] })}>Add charge</button> : undefined}><div className="rtw-scroll"><table className="rtw-table"><thead><tr><th>Charge</th><th>Applies to</th><th>Treatment</th><th>Charging basis</th><th>Amount</th>{editing ? <th>Action</th> : null}</tr></thead><tbody>{tariff.charges.map((row) => <tr key={row.id}><td>{text(row.name, "Charge name", (name) => updateCharge(row.id, { name }))}{editing ? <label className="activity-rate__check"><input type="checkbox" checked={row.mandatory} onChange={(event) => updateCharge(row.id, { mandatory: event.target.checked })} /> Mandatory</label> : <small>{row.mandatory ? "Mandatory" : "Optional"}</small>}</td><td><OptionScope value={row.optionIds} allOptions={row.allOptions} options={options} editing={editing} onChange={(optionIds, allOptions) => updateCharge(row.id, { optionIds, allOptions })} /></td><td>{select(row.treatment, "Charge treatment", [["included", "Included"], ["additional", "Additional"], ["actuals", "At actuals"], ["not-applicable", "Not applicable"], ["not-provided", "Not provided"]], (treatment) => updateCharge(row.id, { treatment, amount: treatment === "additional" ? row.amount : null }))}</td><td>{select(row.basis, "Charging basis", [["booking", "Per booking"], ["person", "Per person"], ["unit", "Per unit"], ["hour", "Per hour"]], (basis) => updateCharge(row.id, { basis }))}</td><td>{row.treatment === "additional" ? number(row.amount, `${row.name} amount`, (amount) => updateCharge(row.id, { amount }), true) : "—"}</td>{editing ? <td>{remove(row.name, () => patch({ charges: tariff.charges.filter((item) => item.id !== row.id) }))}</td> : null}</tr>)}</tbody></table></div>{!tariff.charges.length ? <div className="rtw-table-foot">No additional charges or inclusions recorded.</div> : null}</Section>

    {(editing || tariff.charges.some((charge) => charge.participantCategory || charge.capacity || charge.from)) && tariff.charges.length ? <Section title="Charge conditions" note="Use participant and date conditions only where the supplier agreed them. Capacity checks the selected extra without multiplying its price."><div className="rtw-scroll"><table className="rtw-table"><thead><tr><th>Charge</th><th>Participant category</th><th>Age from</th><th>Age to</th><th>Capacity</th><th>Valid from</th><th>Valid to</th></tr></thead><tbody>{tariff.charges.map((charge) => <tr key={charge.id}><th scope="row">{charge.name}</th><td>{text(charge.participantCategory ?? "", `${charge.name} participant category`, (participantCategory) => updateCharge(charge.id, { participantCategory }))}</td><td>{number(charge.minAge ?? null, `${charge.name} minimum age`, (minAge) => updateCharge(charge.id, { minAge }))}</td><td>{number(charge.maxAge ?? null, `${charge.name} maximum age`, (maxAge) => updateCharge(charge.id, { maxAge }))}</td><td>{number(charge.capacity ?? null, `${charge.name} capacity`, (capacity) => updateCharge(charge.id, { capacity }))}</td><td>{editing ? <input className="rtw-input" type="date" aria-label={`${charge.name} from`} value={charge.from ?? ""} onChange={(event) => updateCharge(charge.id, { from: event.target.value })} /> : show(charge.from)}</td><td>{editing ? <input className="rtw-input" type="date" aria-label={`${charge.name} to`} value={charge.to ?? ""} onChange={(event) => updateCharge(charge.id, { to: event.target.value })} /> : show(charge.to)}</td></tr>)}</tbody></table></div></Section> : null}

    {(editing || tariff.charges.some((charge) => charge.taxProfileId)) && tariff.charges.some((charge) => charge.treatment === "additional") ? <Section title="Charge tax exceptions" note="A blank profile inherits the card's approved supplier tax profile. Enter a separate approved profile only when a charge differs."><div className="rtw-scroll"><table className="rtw-table"><thead><tr><th>Additional charge</th><th>Approved profile reference</th><th>Rate in profile</th><th>Approval source</th></tr></thead><tbody>{tariff.charges.filter((charge) => charge.treatment === "additional").map((charge) => <tr key={charge.id}><th scope="row">{charge.name}</th><td>{text(charge.taxProfileId ?? "", `${charge.name} tax profile reference`, (taxProfileId) => updateCharge(charge.id, { taxProfileId: taxProfileId || null, approvedTaxRate: taxProfileId ? charge.approvedTaxRate : null, taxApprovalSource: taxProfileId ? charge.taxApprovalSource : "" })) || "Inherit card profile"}</td><td>{charge.taxProfileId && charge.taxProfileId !== tariff.taxProfileId ? editing ? <input className="rtw-input rtw-input--number" type="number" min="0" max="100" step="0.01" aria-label={`${charge.name} approved tax rate percent`} value={charge.approvedTaxRate == null ? "" : charge.approvedTaxRate * 100} onChange={(event) => updateCharge(charge.id, { approvedTaxRate: event.target.value === "" ? null : Number(event.target.value) / 100 })} /> : charge.approvedTaxRate == null ? "Pending" : `${charge.approvedTaxRate * 100}%` : "Inherited"}</td><td>{charge.taxProfileId && charge.taxProfileId !== tariff.taxProfileId ? text(charge.taxApprovalSource ?? "", `${charge.name} tax approval source`, (taxApprovalSource) => updateCharge(charge.id, { taxApprovalSource })) : "Inherited"}</td></tr>)}</tbody></table></div></Section> : null}

    {(editing || tariff.adjustments.length > 0) ? <Section title="Date-specific adjustments" note="Use only for supplier-agreed exceptions. Pricing resolves using the activity service date." action={editing ? <button className="rtw-button" type="button" onClick={() => patch({ adjustments: [...tariff.adjustments, { id: id("date"), name: "New date rule", optionIds: [], from: "", to: "", treatment: "additional", amount: null, stacking: "combine" }] })}>Add date rule</button> : undefined}><div className="rtw-scroll"><table className="rtw-table"><thead><tr><th>Rule</th><th>Applies to</th><th>Dates</th><th>Effect</th><th>Amount</th><th>Combination</th>{editing ? <th>Action</th> : null}</tr></thead><tbody>{tariff.adjustments.map((row) => <tr key={row.id}><td>{text(row.name, "Date rule name", (name) => updateAdjustment(row.id, { name }))}</td><td><OptionScope value={row.optionIds} allOptions={row.optionIds.length === 0} options={options} editing={editing} onChange={(optionIds) => updateAdjustment(row.id, { optionIds })} /></td><td><div className="activity-rate__range">{editing ? <input className="rtw-input" type="date" aria-label="Rule start date" value={row.from} onChange={(event) => updateAdjustment(row.id, { from: event.target.value })} /> : row.from}<span>to</span>{editing ? <input className="rtw-input" type="date" aria-label="Rule end date" value={row.to} onChange={(event) => updateAdjustment(row.id, { to: event.target.value })} /> : row.to}</div></td><td>{select(row.treatment, "Date rule effect", [["additional", "Surcharge"], ["replacement", "Replacement price"], ["unavailable", "Unavailable"]], (treatment) => updateAdjustment(row.id, { treatment }))}{row.treatment === "replacement" ? <div className="activity-rate__basis"><small>Replaces base rate</small>{select(row.personRateId ? `person:${row.personRateId}` : row.bookingRateId ? `booking:${row.bookingRateId}` : row.unitRateId ? `unit:${row.unitRateId}` : "", "Base rate to replace", [["", "Select base price"], ...tariff.personRates.filter((rate) => !row.optionIds.length || row.optionIds.includes(rate.optionId)).map((rate): [string, string] => [`person:${rate.id}`, `${options.find((option) => option.id === rate.optionId)?.name ?? "Option"} / ${rate.category} / ${rate.minAge ?? 0}-${rate.maxAge ?? "any"}`]), ...tariff.bookingRates.filter((rate) => !row.optionIds.length || row.optionIds.includes(rate.optionId)).map((rate): [string, string] => [`booking:${rate.id}`, `${options.find((option) => option.id === rate.optionId)?.name ?? "Option"} / group ${rate.minGroup}-${rate.maxGroup}`]), ...tariff.unitRates.filter((rate) => !row.optionIds.length || row.optionIds.includes(rate.optionId)).map((rate): [string, string] => [`unit:${rate.id}`, `${options.find((option) => option.id === rate.optionId)?.name ?? "Option"} / ${rate.unit}`])], (target) => { const [kind, rateId] = target.split(":"); updateAdjustment(row.id, { personRateId: kind === "person" ? rateId : undefined, bookingRateId: kind === "booking" ? rateId : undefined, unitRateId: kind === "unit" ? rateId : undefined }); })}</div> : null}</td><td>{row.treatment === "unavailable" ? "—" : number(row.amount, "Adjustment amount", (amount) => updateAdjustment(row.id, { amount }), true)}</td><td>{select(row.stacking, "Date rule combination", [["combine", "Combine"], ["replace", "Replace other rule"]], (stacking) => updateAdjustment(row.id, { stacking }))}</td>{editing ? <td>{remove(row.name, () => patch({ adjustments: tariff.adjustments.filter((item) => item.id !== row.id) }))}</td> : null}</tr>)}</tbody></table></div>{!tariff.adjustments.length ? <div className="rtw-table-foot">No exceptional dates configured. Base rates apply throughout the validity range.</div> : null}</Section> : null}

    <Section title="Supplier tax and commercial terms"><div className="activity-rate__facts"><label><span>Tax presentation</span>{select(tariff.taxMode, "Tax presentation", [["inclusive", "Inclusive"], ["exclusive", "Exclusive"]], (taxMode) => patch({ taxMode }))}</label><label><span>Approved tax profile reference</span>{text(tariff.taxProfileId ?? "", "Approved tax profile reference", (taxProfileId) => patch({ taxProfileId: taxProfileId || null }))}</label><label><span>Rate in approved profile (%)</span>{editing ? <input className="rtw-input" type="number" min="0" max="100" step="0.01" aria-label="Rate in approved tax profile, percent" value={tariff.approvedTaxRate == null ? "" : tariff.approvedTaxRate * 100} onChange={(event) => patch({ approvedTaxRate: event.target.value === "" ? null : Number(event.target.value) / 100 })} /> : <strong>{tariff.approvedTaxRate == null ? "Pending approved profile" : `${tariff.approvedTaxRate * 100}%`}</strong>}</label><label><span>Approval source</span>{text(tariff.taxApprovalSource ?? "", "Tax approval source", (taxApprovalSource) => patch({ taxApprovalSource }))}</label><label className="activity-rate__full"><span>Commercial policy</span>{editing ? <textarea className="rtw-input activity-rate__textarea" aria-label="Commercial policy" value={tariff.commercialPolicy} onChange={(event) => patch({ commercialPolicy: event.target.value })} /> : <strong>{show(tariff.commercialPolicy)}</strong>}</label></div><div className="rtw-table-foot">Enter the rate from an approved supplier tax profile and cite its approval. Agency markup and customer tax are calculated separately. Session availability is confirmed separately.</div></Section>
  </div>;
}

export function ActivityTestRate({ card, options }: { card: RateCardDetail; options: ActivityOption[] }) {
  const tariff = card.activityTariff!;
  const [input, setInput] = useState<ActivityQuoteInput>(() => { const optionId = options[0]?.id ?? ""; const firstPerson = tariff.personRates.find((rate) => rate.optionId === optionId); return { date: tariff.validFrom, optionId, method: firstPerson ? "person" : tariff.bookingRates.some((rate) => rate.optionId === optionId) ? "booking" : "unit", participants: [{ category: firstPerson?.category ?? "Everyone", age: firstPerson?.minAge ?? null, quantity: 2 }], groupSize: 2, unitRateId: tariff.unitRates.find((rate) => rate.optionId === optionId)?.id ?? "", unitQuantity: 1, hours: 2, days: 1, selectedChargeIds: [], transferCostedElsewhere: false }; });
  const set = <K extends keyof ActivityQuoteInput>(key: K, value: ActivityQuoteInput[K]) => setInput((current) => ({ ...current, [key]: value }));
  const available = useMemo(() => methods.filter(({ id: method }) => tariff.methods.includes(method) && (method === "person" ? tariff.personRates : method === "booking" ? tariff.bookingRates : tariff.unitRates).some((row) => row.optionId === input.optionId)), [tariff, input.optionId]);
  const result = calculateActivityQuote(tariff, options, input);
  const selectedOption = options.find((option) => option.id === input.optionId);
  const relevantCategories = [...new Set([...tariff.personRates.filter((rate) => rate.optionId === input.optionId).map((rate) => rate.category), ...tariff.charges.filter((charge) => charge.allOptions || charge.optionIds.includes(input.optionId)).map((charge) => charge.participantCategory).filter((value): value is string => !!value), "Adult", "Child", "Everyone"])];
  const needsParticipants = input.method === "person" || tariff.charges.some((charge) => charge.basis === "person" && charge.treatment === "additional" && (charge.mandatory || input.selectedChargeIds.includes(charge.id)) && (charge.allOptions || charge.optionIds.includes(input.optionId))) || selectedOption?.minAge != null || selectedOption?.maxAge != null;
  const availableUnits = tariff.unitRates.filter((rate) => rate.optionId === input.optionId);
  const visibleCharges = tariff.charges.filter((charge) => !charge.mandatory && (charge.allOptions || charge.optionIds.includes(input.optionId)));
  const onRequestRows = applicableOnRequestRows(tariff, input);
  const setConfirmedRate = (rateId: string, update: Partial<{ amount: number | null; source: string; validUntil: string }>) => setInput((current) => ({ ...current, confirmedOnRequestRates: { ...current.confirmedOnRequestRates, [rateId]: { amount: current.confirmedOnRequestRates?.[rateId]?.amount ?? null, source: current.confirmedOnRequestRates?.[rateId]?.source ?? "", ...update } } }));
  return <div className="rtw-test activity-test"><section><div className="rtw-test__head"><h2>Activity request</h2><p>Choose one option and one base-pricing method.</p></div><div className="rtw-test__fields">
    <label><span>Service date</span><input type="date" value={input.date} onChange={(event) => set("date", event.target.value)} /></label>
    {selectedOption?.sessions?.length ? <label><span>Requested session</span><select value={input.session ?? ""} onChange={(event) => set("session", event.target.value)}><option value="">Select session</option>{selectedOption.sessions.map((session) => <option key={session} value={session}>{session}</option>)}</select></label> : null}
    <label><span>Service option</span><select value={input.optionId} onChange={(event) => { const optionId = event.target.value; const firstPerson = tariff.personRates.find((rate) => rate.optionId === optionId); const method = firstPerson ? "person" : tariff.bookingRates.some((rate) => rate.optionId === optionId) ? "booking" : "unit"; setInput((current) => ({ ...current, optionId, method, participants: [{ category: firstPerson?.category ?? "Everyone", age: firstPerson?.minAge ?? null, quantity: 2 }], unitRateId: tariff.unitRates.find((rate) => rate.optionId === optionId)?.id ?? "", unitSelections: undefined, session: "", selectedChargeIds: [], confirmedOnRequestRates: {} })); }}><option value="">Select option</option>{options.map((option) => <option key={option.id} value={option.id}>{option.name}</option>)}</select></label>
    <label><span>Pricing method</span><select value={input.method} onChange={(event) => set("method", event.target.value as ActivityMethod)}>{available.map((item) => <option key={item.id} value={item.id}>{item.label}</option>)}{!available.some((item) => item.id === input.method) ? <option value={input.method}>{methods.find((item) => item.id === input.method)?.label ?? input.method} · no rate</option> : null}</select></label>
    {input.method !== "person" ? <label><span>Group size{input.method === "unit" ? " for capacity" : ""}</span><input type="number" min="1" value={input.groupSize} onChange={(event) => set("groupSize", Number(event.target.value))} /></label> : null}
    {onRequestRows.length ? <div className="activity-test__on-request">{onRequestRows.map((row) => <div key={row.id}><strong>{"category" in row ? row.category : "unit" in row ? row.unit : row.basisLabel}</strong><label><span>Confirmed supplier rate</span><input type="number" min="0" value={input.confirmedOnRequestRates?.[row.id]?.amount ?? ""} onChange={(event) => setConfirmedRate(row.id, { amount: asNumber(event.target.value) })} /></label><label><span>Quote source / reference</span><input value={input.confirmedOnRequestRates?.[row.id]?.source ?? ""} onChange={(event) => setConfirmedRate(row.id, { source: event.target.value })} /></label><label><span>Quote valid until</span><input type="date" value={input.confirmedOnRequestRates?.[row.id]?.validUntil ?? ""} onChange={(event) => setConfirmedRate(row.id, { validUntil: event.target.value })} /></label></div>)}</div> : null}
    {needsParticipants ? <div className="activity-test__participants"><strong>Participants</strong>{input.participants.map((participant, index) => <div key={index}><select aria-label={`Participant ${index + 1} category`} value={participant.category} onChange={(event) => set("participants", input.participants.map((item, rowIndex) => rowIndex === index ? { ...item, category: event.target.value } : item))}>{relevantCategories.map((category) => <option key={category} value={category}>{category}</option>)}{!relevantCategories.includes(participant.category) ? <option value={participant.category}>{participant.category}</option> : null}</select>{(selectedOption?.minAge != null || selectedOption?.maxAge != null || tariff.personRates.some((rate) => rate.optionId === input.optionId && rate.category === participant.category && (rate.minAge != null || rate.maxAge != null)) || tariff.charges.some((charge) => charge.participantCategory === participant.category && (charge.minAge != null || charge.maxAge != null))) ? <input type="number" min="0" aria-label={`Participant ${index + 1} age`} placeholder="Age" value={participant.age ?? ""} onChange={(event) => set("participants", input.participants.map((item, rowIndex) => rowIndex === index ? { ...item, age: asNumber(event.target.value) } : item))} /> : null}<input type="number" min="0" aria-label={`Participant ${index + 1} quantity`} value={participant.quantity} onChange={(event) => set("participants", input.participants.map((item, rowIndex) => rowIndex === index ? { ...item, quantity: Number(event.target.value) } : item))} /><button type="button" onClick={() => set("participants", input.participants.filter((_, rowIndex) => rowIndex !== index))}>Remove</button></div>)}<button type="button" onClick={() => set("participants", [...input.participants, { category: relevantCategories[0] ?? "Everyone", age: null, quantity: 1 }])}>Add participant category</button></div> : null}
    {input.method === "unit" && !input.unitSelections?.length ? <><label><span>Unit tariff</span><select value={input.unitRateId} onChange={(event) => set("unitRateId", event.target.value)}><option value="">Select unit</option>{availableUnits.map((rate) => <option key={rate.id} value={rate.id}>{rate.unit} · {rate.basis}</option>)}</select></label><label><span>Unit quantity</span><input type="number" min="1" value={input.unitQuantity} onChange={(event) => set("unitQuantity", Number(event.target.value))} /></label>{availableUnits.find((rate) => rate.id === input.unitRateId)?.basis === "hour" ? <label><span>Chargeable hours</span><input type="number" min="1" value={input.hours} onChange={(event) => set("hours", Number(event.target.value))} /></label> : null}{availableUnits.find((rate) => rate.id === input.unitRateId)?.basis === "day" ? <label><span>Chargeable days</span><input type="number" min="1" value={input.days} onChange={(event) => set("days", Number(event.target.value))} /></label> : null}</> : null}
    {input.method === "unit" ? <div className="activity-test__participants"><strong>Selected units</strong>{(input.unitSelections ?? []).map((selection, index) => { const rate = availableUnits.find((item) => item.id === selection.rateId); return <div key={index}><select aria-label={`Unit ${index + 1} type`} value={selection.rateId} onChange={(event) => set("unitSelections", input.unitSelections!.map((item, rowIndex) => rowIndex === index ? { ...item, rateId: event.target.value } : item))}>{availableUnits.map((item) => <option key={item.id} value={item.id}>{item.unit} ? {item.basis}</option>)}</select><input type="number" min="1" aria-label={`Unit ${index + 1} quantity`} value={selection.quantity} onChange={(event) => set("unitSelections", input.unitSelections!.map((item, rowIndex) => rowIndex === index ? { ...item, quantity: Number(event.target.value) } : item))} />{rate?.basis === "hour" ? <input type="number" min="1" aria-label={`Unit ${index + 1} hours`} value={selection.hours ?? input.hours} onChange={(event) => set("unitSelections", input.unitSelections!.map((item, rowIndex) => rowIndex === index ? { ...item, hours: Number(event.target.value) } : item))} /> : null}{rate?.basis === "day" ? <input type="number" min="1" aria-label={`Unit ${index + 1} days`} value={selection.days ?? input.days} onChange={(event) => set("unitSelections", input.unitSelections!.map((item, rowIndex) => rowIndex === index ? { ...item, days: Number(event.target.value) } : item))} /> : null}<button type="button" onClick={() => set("unitSelections", input.unitSelections!.filter((_, rowIndex) => rowIndex !== index))}>Remove</button></div>; })}<button type="button" onClick={() => set("unitSelections", [...(input.unitSelections ?? [{ rateId: input.unitRateId || availableUnits[0]?.id || "", quantity: input.unitQuantity, hours: input.hours, days: input.days }]), { rateId: availableUnits[0]?.id ?? "", quantity: 1, hours: input.hours, days: input.days }])}>Add another unit</button></div> : null}
    {visibleCharges.length ? <fieldset className="activity-test__extras"><legend>Optional extras</legend>{visibleCharges.map((charge) => <label key={charge.id}><input type="checkbox" checked={input.selectedChargeIds.includes(charge.id)} onChange={(event) => set("selectedChargeIds", event.target.checked ? [...input.selectedChargeIds, charge.id] : input.selectedChargeIds.filter((item) => item !== charge.id))} />{charge.name}</label>)}</fieldset> : null}
    <label className="activity-test__wide"><input type="checkbox" checked={input.transferCostedElsewhere} onChange={(event) => set("transferCostedElsewhere", event.target.checked)} />Transfer already costed elsewhere</label>
    <div className="activity-test__wide"><strong>{selectedOption?.name ?? "Select an option"}</strong><small>{selectedOption?.session ?? ""} · Availability is checked separately.</small></div>
  </div></section><section><div className="rtw-test__head"><h2>Supplier cost</h2><p>Version {result.cardVersion} · {card.vendor} · {card.currency}</p></div><div className="activity-test__result"><div className="activity-test__lines">{result.lines.map((line, index) => <div key={`${line.label}-${index}`}><span><strong>{line.label}</strong><small>{line.detail}</small></span><b>{line.amount == null ? "Unresolved" : formatMoney(line.amount, card.currency)}</b></div>)}<div><span>Additional charges</span><b>{formatMoney(result.extras, card.currency)}</b></div><div><span>Supplier tax</span><b>{result.tax == null ? "Profile required" : formatMoney(result.tax, card.currency)}</b></div></div><div className="activity-test__total"><span>Total supplier cost</span><strong>{result.supplierTotal == null ? "Needs review" : formatMoney(result.supplierTotal, card.currency)}</strong><small>{result.actuals.length ? `Base price plus actuals: ${result.actuals.join(", ")}` : "Agency selling price is set separately in Proposal."}</small></div>{result.includedComponents.length ? <p className="activity-test__included"><strong>Included:</strong> {result.includedComponents.join(", ")}. Do not add these again elsewhere.</p> : null}{result.externalRequirements.length ? <p className="activity-test__external"><strong>Price separately:</strong> {result.externalRequirements.join(", ")}.</p> : null}<p className={`activity-test__availability activity-test__availability--${result.availability}`}><strong>{result.availability === "unavailable" ? "Session unavailable" : result.availability === "available" ? "Session listed" : "Availability unconfirmed"}</strong> · {result.availabilityMessage}</p>{result.blockers.length ? <div className="activity-test__blockers"><strong>Resolve before quoting</strong><ul>{result.blockers.map((message) => <li key={message}>{message}</li>)}</ul></div> : <p className="activity-test__ok">Saved supplier rates resolve for these inputs. Confirm session availability before booking.</p>}</div></section></div>;
}
